class Solution {
    fun minCost(grid:Array<IntArray>):Int{
        val rows=grid.size;
        val cols=grid[0].size;
        val directions=arrayOf(intArrayOf(0,1),intArrayOf(0,-1),intArrayOf(1,0),intArrayOf(-1,0));
        val dist=Array(rows){
            IntArray(cols){
                Int.MAX_VALUE
            }
        };
        val deque=java.util.ArrayDeque<IntArray>();
        dist[0][0]=0;
        deque.addFirst(intArrayOf(0,0));
        while(deque.isNotEmpty()){
            val cell=deque.removeFirst();
            val row=cell[0];
            val col=cell[1];
            for(direction in 0..3){
                val nextRow=row+directions[direction][0];
                val nextCol=col+directions[direction][1];
                if(nextRow !in 0 until rows||nextCol !in 0 until cols)continue;
                val weight=if(grid[row][col]==direction+1)0 else 1;
                val newDistance=dist[row][col]+weight;
                if(newDistance<dist[nextRow][nextCol]){
                    dist[nextRow][nextCol]=newDistance;
                    if(weight==0)deque.addFirst(intArrayOf(nextRow,nextCol))else deque.addLast(intArrayOf(nextRow,nextCol))
                }
            }
        };
        return dist[rows-1][cols-1]
    }
}

